1	package br.com.loja.checkout;
2	
3	import static br.com.loja.checkout.CodigoErro.*;
4	
5	import br.com.loja.checkout.clube.NivelClube;
6	import br.com.loja.checkout.clube.Vantagens;
7	import br.com.loja.checkout.cupom.Cupom;
8	import br.com.loja.checkout.entrega.ModalidadeEntrega;
9	import br.com.loja.checkout.pagamento.Cobranca;
10	import br.com.loja.checkout.pagamento.FormaPagamento;
11	import java.math.BigDecimal;
12	import java.util.List;
13	import java.util.Optional;
14	import org.springframework.stereotype.Service;
15	
16	@Service
17	public class ServicoResumo {
18	
19	    private final Catalogo<NivelClube> niveis;
20	    private final Catalogo<ModalidadeEntrega> modalidades;
21	    private final Catalogo<Cupom> cupons;
22	    private final Catalogo<FormaPagamento> formas;
23	
24	    public ServicoResumo(
25	            List<NivelClube> niveis,
26	            List<ModalidadeEntrega> modalidades,
27	            List<Cupom> cupons,
28	            List<FormaPagamento> formas) {
29	        this.niveis = new Catalogo<>(niveis, NivelClube::codigo);
30	        this.modalidades = new Catalogo<>(modalidades, ModalidadeEntrega::codigo);
31	        this.cupons = new Catalogo<>(cupons, Cupom::codigo);
32	        this.formas = new Catalogo<>(formas, FormaPagamento::codigo);
33	    }
34	
35	    public ResumoResponse calcular(ResumoRequest pedido) {
36	        Carrinho carrinho = carrinho(pedido.itens());
37	        NivelClube nivel = exigir(niveis.buscar(pedido.nivelClube()), NIVEL_CLUBE_INVALIDO);
38	        Regiao regiao = regiao(pedido.regiao());
39	        ModalidadeEntrega entrega = exigir(modalidades.buscar(pedido.modalidadeEntrega()), MODALIDADE_INVALIDA);
40	        if (!entrega.atende(carrinho)) {
41	            throw new PedidoRecusadoException(MODALIDADE_INDISPONIVEL);
42	        }
43	        Optional<Cupom> cupom = cupom(pedido.cupom(), carrinho);
44	        FormaPagamento forma = exigir(formas.buscar(pedido.formaPagamento()), FORMA_PAGAMENTO_INVALIDA);
45	        int parcelas = pedido.parcelas() == null ? 1 : pedido.parcelas();
46	        if (!forma.aceitaParcelas(parcelas)) {
47	            throw new PedidoRecusadoException(PARCELAMENTO_INVALIDO);
48	        }
49	
50	        BigDecimal subtotal = carrinho.subtotal();
51	        Vantagens vantagens = nivel.vantagens(subtotal);
52	        BigDecimal frete = vantagens.freteGratis() ? Dinheiro.ZERO : entrega.frete(carrinho);
53	        BigDecimal desconto = cupom.map(c -> c.desconto(carrinho, frete)).orElse(Dinheiro.ZERO);
54	        BigDecimal seguro = regiao.seguro(subtotal);
55	        BigDecimal totalPedido = subtotal.subtract(desconto).add(frete).add(seguro);
56	
57	        if (!forma.aceitaTotal(totalPedido)) {
58	            throw new PedidoRecusadoException(FORMA_PAGAMENTO_INDISPONIVEL);
59	        }
60	        Cobranca cobranca = forma.cobrar(totalPedido, parcelas);
61	
62	        return new ResumoResponse(
63	                subtotal,
64	                desconto,
65	                frete,
66	                entrega.prazoDias(),
67	                seguro,
68	                cobranca.totalFinal().subtract(totalPedido),
69	                cobranca.totalFinal(),
70	                parcelas,
71	                cobranca.valorParcela(),
72	                vantagens.creditoProximaCompra(),
73	                vantagens.brinde());
74	    }
75	
76	    private Carrinho carrinho(List<ItemRequest> itens) {
77	        if (itens == null || itens.isEmpty() || itens.stream().anyMatch(i -> i == null || !valido(i))) {
78	            throw new PedidoRecusadoException(PEDIDO_INVALIDO);
79	        }
80	        return new Carrinho(itens.stream()
81	                .map(i -> new Item(i.nome(), i.precoUnitario(), i.quantidade(), i.pesoKg()))
82	                .toList());
83	    }
84	
85	    private boolean valido(ItemRequest item) {
86	        return item.precoUnitario() != null && item.precoUnitario().signum() > 0
87	                && item.quantidade() != null && item.quantidade() > 0
88	                && item.pesoKg() != null && item.pesoKg().signum() > 0;
89	    }
90	
91	    private Regiao regiao(String codigo) {
92	        try {
93	            return Regiao.valueOf(codigo);
94	        } catch (IllegalArgumentException | NullPointerException e) {
95	            throw new PedidoRecusadoException(REGIAO_INVALIDA);
96	        }
97	    }
98	
99	    private Optional<Cupom> cupom(String codigo, Carrinho carrinho) {
100	        if (codigo == null) {
101	            return Optional.empty();
102	        }
103	        Cupom cupom = exigir(cupons.buscar(codigo), CUPOM_INVALIDO);
104	        if (!cupom.aplicavel(carrinho)) {
105	            throw new PedidoRecusadoException(CUPOM_NAO_APLICAVEL);
106	        }
107	        return Optional.of(cupom);
108	    }
109	
110	    private static <T> T exigir(Optional<T> caso, CodigoErro erro) {
111	        return caso.orElseThrow(() -> new PedidoRecusadoException(erro));
112	    }
113	}
