3	import java.math.BigDecimal;
4	import java.util.List;
5	
6	public record Carrinho(List<Item> itens) {
7	
8	    public BigDecimal subtotal() {
9	        return Dinheiro.arredondar(itens.stream().map(Item::subtotal).reduce(BigDecimal.ZERO, BigDecimal::add));
10	    }
11	
12	    /** Peso do pedido, sem arredondar. */
13	    public BigDecimal pesoKg() {
14	        return itens.stream().map(Item::pesoTotal).reduce(BigDecimal.ZERO, BigDecimal::add);
15	    }
16	}
