1	package br.com.loja.checkout;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	
6	public final class Dinheiro {
7	
8	    public static final BigDecimal ZERO = arredondar(BigDecimal.ZERO);
9	
10	    private Dinheiro() {
11	    }
12	
13	    /** Arredonda para centavos, meio para o par. */
14	    public static BigDecimal arredondar(BigDecimal valor) {
15	        return valor.setScale(2, RoundingMode.HALF_EVEN);
16	    }
17	
18	    public static BigDecimal percentual(BigDecimal base, String taxa) {
19	        return arredondar(base.multiply(new BigDecimal(taxa)));
20	    }
21	}
