1	package br.com.loja.checkout;
2	
3	import java.util.Collection;
4	import java.util.HashMap;
5	import java.util.Map;
6	import java.util.Optional;
7	import java.util.function.Function;
8	
9	/** Encontra um caso pelo código, sem sequência de condições. */
10	public class Catalogo<T> {
11	
12	    private final Map<String, T> porCodigo = new HashMap<>();
13	
14	    public Catalogo(Collection<T> casos, Function<T, String> codigo) {
15	        casos.forEach(c -> porCodigo.put(codigo.apply(c), c));
16	    }
17	
18	    public Optional<T> buscar(String codigo) {
19	        return Optional.ofNullable(codigo == null ? null : porCodigo.get(codigo));
20	    }
