1	package br.com.loja.checkout.pagamento;
2	
3	import br.com.loja.checkout.Dinheiro;
4	import java.math.BigDecimal;
5	import java.math.MathContext;
6	import org.springframework.stereotype.Component;
7	
8	@Component
9	public class Cartao implements FormaPagamento {
10	
11	    private static final int MAX_PARCELAS = 12;
12	    private static final int MAX_PARCELAS_SEM_JUROS = 3;
13	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
14	
15	    public String codigo() {
16	        return "CARTAO";
17	    }
18	
19	    public boolean aceitaParcelas(int parcelas) {
20	        return parcelas >= 1 && parcelas <= MAX_PARCELAS;
21	    }
22	
23	    public boolean aceitaTotal(BigDecimal totalPedido) {
24	        return true;
25	    }
26	
27	    public Cobranca cobrar(BigDecimal totalPedido, int parcelas) {
28	        if (parcelas <= MAX_PARCELAS_SEM_JUROS) {
29	            return new Cobranca(totalPedido, Dinheiro.arredondar(totalPedido.divide(BigDecimal.valueOf(parcelas), MathContext.DECIMAL128)));
30	        }
31	        BigDecimal fator = BigDecimal.ONE.add(TAXA_MENSAL).pow(parcelas, MathContext.DECIMAL128);
32	        BigDecimal divisor = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(fator, MathContext.DECIMAL128));
33	        BigDecimal parcela = Dinheiro.arredondar(totalPedido.multiply(TAXA_MENSAL).divide(divisor, MathContext.DECIMAL128));
34	        return new Cobranca(Dinheiro.arredondar(parcela.multiply(BigDecimal.valueOf(parcelas))), parcela);
35	    }
36	}
